1	//! Windowed workflow-history reads for the ops console.
2	
3	use std::sync::Arc;
4	
5	use aion::Engine;
6	use aion_core::{Event, PayloadElision, WorkflowId};
7	use aion_proto::{ProtoDescribeWorkflowRequest, ProtoWorkflowId, WireError};
8	use axum::{Json, extract::State};
9	use serde::{Deserialize, Serialize};
10	use serde_json::{Map, Value};
11	use uuid::Uuid;
12	
13	use super::auth::HttpCaller;
14	use super::error::HttpWireError;
15	use crate::{NamespaceOperation, ServerError, ServerState, WorkflowTarget};
16	
17	const DEFAULT_HISTORY_LIMIT: u32 = 500;
18	const MAX_WINDOW_LIMIT: u32 = 2_000;
19	const DEFAULT_PAYLOAD_LIMIT_BYTES: u32 = 2_048;
20	
21	/// Request for one ascending workflow-history window.
22	#[derive(Debug, Deserialize)]
23	pub(crate) struct HistoryFetchRequest {
24	    namespace: String,
25	    workflow_id: String,
26	    #[serde(default)]
27	    from_seq: Option<u64>,
28	    #[serde(default)]
29	    limit: Option<u32>,
30	    #[serde(default)]
31	    payload_limit_bytes: Option<u32>,
32	}
33	
34	/// One projected workflow-history window.
35	#[derive(Debug, Serialize)]
36	pub(crate) struct HistoryFetchResponse {
37	    events: Vec<Value>,
38	    next_from_seq: Option<u64>,
39	    head_seq: u64,
40	}
41	
42	/// Request for one full workflow-history event.
43	#[derive(Debug, Deserialize)]
44	pub(crate) struct EventFetchRequest {
45	    namespace: String,
46	    workflow_id: String,
47	    seq: u64,
48	}
49	
50	/// One full workflow-history event.
51	#[derive(Debug, Serialize)]
52	pub(crate) struct EventFetchResponse {
53	    event: Event,
54	}
55	
56	/// `POST /workflows/history`.
57	pub(crate) async fn fetch_history(
58	    State(state): State<ServerState>,
59	    HttpCaller(caller): HttpCaller,
60	    Json(request): Json<HistoryFetchRequest>,
61	) -> Result<Json<HistoryFetchResponse>, HttpWireError> {
62	    let workflow_id = parse_workflow_id(&request.workflow_id)?;
63	    let engine = scoped_engine(
64	        &state,
65	        &caller,
66	        &request.namespace,
67	        &request.workflow_id,
68	        &workflow_id,
69	    )
70	    .await?;
71	    let from_seq = request.from_seq.map_or(0, |seq| seq);
72	    let limit = request
73	        .limit
74	        .map_or(DEFAULT_HISTORY_LIMIT, |limit| limit)
75	        .clamp(1, MAX_WINDOW_LIMIT) as usize;
76	    let payload_limit = request
77	        .payload_limit_bytes
78	        .map_or(DEFAULT_PAYLOAD_LIMIT_BYTES, |limit| limit);
79	    let ranged = engine
80	        .store()
81	        .read_history_from(&workflow_id, from_seq)
82	        .await
83	        .map_err(store_error)?;
84	
85	    // A ranged read beyond the head cannot report the head. Fall back to the
86	    // complete snapshot only for that empty-tail edge, and project the range
87	    // from the same snapshot so a concurrent append cannot create a gap.
88	    let (mut tail, head_seq) = if ranged.is_empty() {
89	        let mut history = engine
90	            .store()
91	            .read_history(&workflow_id)
92	            .await
93	            .map_err(store_error)?;
94	        let head_seq = history.last().map_or(0, Event::seq);
95	        history.retain(|event| event.seq() >= from_seq);
96	        (history, head_seq)
97	    } else {
98	        let head_seq = ranged.last().map_or(0, Event::seq);
99	        (ranged, head_seq)
100	    };
101	
102	    let next_from_seq = tail.get(limit).map(Event::seq);
103	    tail.truncate(limit);
104	    let events = tail
105	        .into_iter()
106	        .map(|event| project_event(event, payload_limit))
107	        .collect::<Result<Vec<_>, _>>()?;
108	
109	    Ok(Json(HistoryFetchResponse {
110	        events,
111	        next_from_seq,
112	        head_seq,
113	    }))
114	}
115	
116	/// `POST /workflows/event`.
117	pub(crate) async fn fetch_event(
118	    State(state): State<ServerState>,
119	    HttpCaller(caller): HttpCaller,
120	    Json(request): Json<EventFetchRequest>,
121	) -> Result<Json<EventFetchResponse>, HttpWireError> {
122	    let workflow_id = parse_workflow_id(&request.workflow_id)?;
123	    let engine = scoped_engine(
124	        &state,
125	        &caller,
126	        &request.namespace,
127	        &request.workflow_id,
128	        &workflow_id,
129	    )
130	    .await?;
131	    let event = engine
132	        .store()
133	        .read_history_from(&workflow_id, request.seq)
134	        .await
135	        .map_err(store_error)?
136	        .into_iter()
137	        .find(|event| event.seq() == request.seq)
138	        .ok_or_else(|| {
139	            HttpWireError(WireError::not_found(format!(
140	                "workflow event {} at seq {} was not found",
141	                request.workflow_id, request.seq
142	            )))
143	        })?;
144	
145	    Ok(Json(EventFetchResponse { event }))
146	}
