148	async fn scoped_engine(
149	    state: &ServerState,
150	    caller: &crate::CallerIdentity,
151	    namespace: &str,
152	    workflow_id_wire: &str,
153	    workflow_id: &WorkflowId,
154	) -> Result<Arc<Engine>, HttpWireError> {
155	    let describe = ProtoDescribeWorkflowRequest {
156	        namespace: namespace.to_owned(),
157	        workflow_id: Some(ProtoWorkflowId {
158	            uuid: workflow_id_wire.to_owned(),
159	        }),
160	        run_id: None,
161	        include_history: false,
162	    };
163	    let target = WorkflowTarget::workflow(workflow_id);
164	    let scoped = state
165	        .namespace_guard()
166	        .scope(caller, &NamespaceOperation::describe(&describe, target))
167	        .await
168	        .map_err(|error| HttpWireError(error.to_wire_error()))?;
169	    scoped
170	        .engine()
171	        .cloned()
172	        .map_err(|error| HttpWireError(error.to_wire_error()))
173	}
