181	fn store_error(error: aion_store::StoreError) -> HttpWireError {
182	    HttpWireError(ServerError::from(error).to_wire_error())
183	}
184	
185	fn project_event(event: Event, payload_limit: u32) -> Result<Value, HttpWireError> {
186	    let mut value = serde_json::to_value(event).map_err(|error| {
187	        HttpWireError(WireError::backend(format!(
188	            "workflow event JSON encoding failed: {error}"
189	        )))
190	    })?;
191	    if payload_limit != 0 {
192	        elide_payload_bytes(&mut value, u64::from(payload_limit))?;
193	    }
194	    Ok(value)
195	}
196	
197	fn elide_payload_bytes(value: &mut Value, limit: u64) -> Result<(), HttpWireError> {
198	    match value {
199	        Value::Array(values) => {
200	            for value in values {
201	                elide_payload_bytes(value, limit)?;
202	            }
203	        }
204	        Value::Object(object) => {
205	            if is_payload_object(object) {
206	                if let Some(bytes) = object.get_mut("bytes") {
207	                    if let Some(size_bytes) = payload_byte_len(bytes).filter(|size| *size > limit) {
208	                        *bytes = elision_value(size_bytes)?;
209	                    }
210	                }
211	            } else {
212	                for value in object.values_mut() {
213	                    elide_payload_bytes(value, limit)?;
214	                }
215	            }
216	        }
217	        _ => {}
218	    }
219	    Ok(())
220	}
221	
222	fn elision_value(size_bytes: u64) -> Result<Value, HttpWireError> {
223	    serde_json::to_value(PayloadElision::new(size_bytes)).map_err(|error| {
224	        HttpWireError(WireError::backend(format!(
225	            "payload elision encoding failed: {error}"
226	        )))
227	    })
228	}
229	
230	fn is_payload_object(object: &Map<String, Value>) -> bool {
231	    object.get("content_type").is_some_and(Value::is_string) && object.contains_key("bytes")
232	}
233	
234	fn payload_byte_len(value: &Value) -> Option<u64> {
235	    value
236	        .as_array()
237	        .and_then(|bytes| u64::try_from(bytes.len()).ok())
238	}

