13	 * started attempt is durably enumerated by `ActivityStarted`); this enumeration
14	 * only badges which rows have a RETAINED durable transcript. An empty list is the
15	 * honest answer for a pre-retention run; a failure is visible state
16	 * (`loadError`), never a throw into render and never swallowed.
17	 *
18	 * The endpoint enumerates ONE generation, so a workflow whose loaded history
19	 * spans several generations of a continue-as-new chain is enumerated once per
20	 * generation and the rows are concatenated — each row names its own run, so the
21	 * union stays unambiguous. If ANY generation's read fails the whole result is an
22	 * error: a partial union badged as complete would silently under-report which
23	 * attempts have a retained transcript.
24	 */
25	
26	export type UseRetainedStreamsOptions = {
27	  /** The workflow to enumerate; `null` leaves the hook idle. */
28	  workflowId: WorkflowId | null;
29	  /**
30	   * The generations to enumerate; empty leaves the hook idle. A run is required
31	   * by the server on every request: a chain-wide enumeration would return several
32	   * generations' streams under pairwise-colliding coordinates, so there is no
33	   * run-less answer to give.
34	   */
35	  runIds: readonly RunId[];
36	  /** The namespace scope; `null` leaves the hook idle (no scope to authorize). */
37	  namespace: Namespace | null;
38	  /** Override the REST reader (tests); defaults to the configured client. */
39	  reader?: Pick<TranscriptReadClient, 'listStreams'>;
40	};
41	
42	export type UseRetainedStreamsResult = {
43	  /** The retained streams, as enumerated by the server (may be empty). */
44	  streams: RetainedStreamHead[];
45	  loadState: 'idle' | 'loading' | 'ready' | 'error';
46	  loadError: Error | null;
47	};
48	
49	export function useRetainedStreams(options: UseRetainedStreamsOptions): UseRetainedStreamsResult {
50	  const { workflowId, namespace } = options;
51	  // The effect must not re-run because the caller built a fresh array with the
52	  // same contents; the identity it depends on is the RUNS, not the array.
53	  const runsKey = options.runIds.join('\u0000');
54	  const [streams, setStreams] = useState<RetainedStreamHead[]>([]);
55	  const [loadState, setLoadState] = useState<UseRetainedStreamsResult['loadState']>('idle');
56	  const [loadError, setLoadError] = useState<Error | null>(null);
57	
58	  useEffect(() => {
59	    const runIds = runsKey === '' ? [] : (runsKey.split('\u0000') as RunId[]);
60	    if (workflowId === null || runIds.length === 0 || namespace === null) {
61	      setStreams([]);
62	      setLoadState('idle');
63	      setLoadError(null);
64	      return;
65	    }
66	
67	    let active = true;
68	    const reader = options.reader ?? createConfiguredTranscriptReader({ namespace });
69	    setStreams([]);
70	    setLoadState('loading');
71	    setLoadError(null);
72	
73	    Promise.all(runIds.map((runId) => reader.listStreams(namespace, workflowId, runId)))
74	      .then((pages) => {
75	        if (!active) {
76	          return;
77	        }
78	        setStreams(pages.flat());
79	        setLoadState('ready');
80	      })
81	      .catch((error: unknown) => {
82	        if (!active) {
83	          return;
84	        }
85	        setLoadState('error');
86	        setLoadError(error instanceof Error ? error : new Error(String(error)));
87	      });
88	
89	    return () => {
90	      active = false;
91	    };
92	  }, [workflowId, runsKey, namespace, options.reader]);
93	
94	  return useMemo(() => ({ streams, loadState, loadError }), [streams, loadState, loadError]);
95	}

