75	/// Reconnecting subscription stream.
76	///
77	/// Resumption is per-workflow only: per-workflow `seq` is the only ordering
78	/// that exists, so only [`SubscribeTarget::Workflow`] streams track a cursor
79	/// (`resume_from_seq = last delivered + 1`) and deduplicate by sequence
80	/// number. Filtered and firehose streams are live-only by design: a
81	/// transient disconnect after at least one delivered event ends the stream
82	/// with an honest [`ClientError::Unavailable`] instead of silently
83	/// reattaching a gapped stream; reconnect-live-only is allowed only while
84	/// nothing has been delivered yet.
85	///
86	/// Connect-failure contract (cross-SDK): a failed subscription attach is
87	/// classified exactly like a mid-stream drop. [`ClientError::Unavailable`]
88	/// (transport-level connect failure, DNS/TLS/socket failure, abnormal close)
89	/// is retryable and the stream re-attaches — on the initial attach as well as
90	/// after delivered events — until the caller drops the stream; every other
91	/// taxonomy error (`Unauthenticated`, `NamespaceDenied`, `NotFound`,
92	/// `InvalidArgument`, `Server`, ...) is terminal immediately.
93	pub struct ResumingEventStream {
94	    transport: Arc<dyn WorkflowTransport>,
95	    namespace: String,
96	    target: SubscribeTarget,
97	    last_seq: Option<u64>,
98	    delivered_any: bool,
99	    current: Option<BoxStream<'static, Result<Event, ClientError>>>,
100	    pending_subscribe: Option<BoxFuture<'static, Result<SubscriptionAttempt, ClientError>>>,

180	) -> Result<String, ClientError> {
181	    let (key, subscription) = match request.subscription {
182	        Some(subscription_request::Subscription::PerWorkflow(mut per_workflow)) => {
183	            if let Some(cursor) = resume_from_sequence {
184	                if cursor == 0 {
185	                    return Err(ClientError::invalid_argument(
186	                        "resume_from_seq must be >= 1 (the first sequence number wanted)",
187	                    ));
188	                }
189	                per_workflow.resume_from_seq = Some(cursor);
190	            }
191	            ("per_workflow", encode_subscription(&per_workflow)?)
192	        }
193	        Some(subscription_request::Subscription::Filtered(filtered)) => {
194	            reject_live_only_cursor("filtered", resume_from_sequence)?;
195	            ("filtered", encode_subscription(&filtered)?)
196	        }
197	        Some(subscription_request::Subscription::Firehose(firehose)) => {
198	            reject_live_only_cursor("firehose", resume_from_sequence)?;
199	            ("firehose", encode_subscription(&firehose)?)
200	        }
201	        Some(subscription_request::Subscription::Cluster(cluster)) => {
202	            // The WS3 cluster channel carries its own `after_seq` cursor in the
203	            // subscription body; it does not use the per-workflow resume-cursor
204	            // argument, which is per-workflow-seq-only.
205	            reject_live_only_cursor("cluster", resume_from_sequence)?;
206	            ("cluster", encode_subscription(&cluster)?)
207	        }
208	        Some(subscription_request::Subscription::Transcript(transcript)) => {
209	            // The NOI-5b transcript channel likewise carries its own `after_seq`
210	            // resume cursor (keyed on the commit-allocated `store_seq`) in the
211	            // subscription body, so it does not use the per-workflow-seq resume
212	            // argument.
213	            reject_live_only_cursor("transcript", resume_from_sequence)?;
214	            ("transcript", encode_subscription(&transcript)?)
215	        }
216	        None => {
217	            return Err(ClientError::invalid_argument(
218	                "subscription request is missing its subscription variant",
219	            ));
220	        }
221	    };
222	    serde_json::to_string(&serde_json::json!({ key: subscription })).map_err(|source| {
223	        ClientError::invalid_argument(format!("failed to encode subscription request: {source}"))
224	    })
225	}
