227	fn encode_subscription<T: serde::Serialize>(value: &T) -> Result<serde_json::Value, ClientError> {
228	    serde_json::to_value(value).map_err(|source| {
229	        ClientError::invalid_argument(format!("failed to encode subscription request: {source}"))
230	    })
231	}
