233	fn reject_live_only_cursor(kind: &str, cursor: Option<u64>) -> Result<(), ClientError> {
234	    if cursor.is_some() {
235	        return Err(ClientError::invalid_argument(format!(
236	            "{kind} event streams are live-only by design; resume cursors are \
237	             valid for per-workflow subscriptions only"
238	        )));
239	    }
240	    Ok(())
241	}
