244	fn apply_headers(
245	    upgrade: &mut tungstenite::handshake::client::Request,
246	    config: &ClientConfig,
247	) -> Result<(), ClientError> {
248	    let headers = upgrade.headers_mut();
249	    if let Some(auth) = &config.auth {
250	        let value = HeaderValue::from_str(&format!("Bearer {}", auth.token()))
251	            .map_err(|_| ClientError::invalid_argument("auth token is not a valid header value"))?;
252	        headers.insert("authorization", value);
253	    }
254	    if let Some(subject) = &config.subject {
255	        let value = HeaderValue::from_str(subject).map_err(|_| {
256	            ClientError::invalid_argument("subject is not a valid x-aion-subject header value")
257	        })?;
258	        headers.insert("x-aion-subject", value);
259	    }
260	    if !config.authorized_namespaces.is_empty() {
261	        let value =
262	            HeaderValue::from_str(&config.authorized_namespaces.join(",")).map_err(|_| {
263	                ClientError::invalid_argument(
264	                    "authorized namespaces are not a valid x-aion-namespaces header value",
265	                )
266	            })?;
267	        headers.insert("x-aion-namespaces", value);
268	    }
269	    Ok(())

