284	/// Adapts one connected socket into the per-attempt event stream.
285	///
286	/// The stream is fused after any error item: a terminal `{"error": ...}`
287	/// frame or a transport failure ends the attempt, and the surrounding resume
288	/// loop decides whether to reconnect (`Unavailable`) or surface the error.
289	fn socket_events(socket: WsStream) -> BoxStream<'static, Result<Event, ClientError>> {
290	    stream::unfold(Some(socket), |state| async move {
291	        let mut socket = state?;
292	        loop {
293	            return match socket.next().await {
294	                None | Some(Err(tungstenite::Error::ConnectionClosed)) => None,
295	                Some(Ok(Message::Text(text))) => match decode_frame(text.as_bytes()) {
296	                    Ok(event) => Some((Ok(event), Some(socket))),
297	                    Err(error) => Some((Err(error), None)),
298	                },
299	                Some(Ok(Message::Binary(bytes))) => match decode_frame(&bytes) {
300	                    Ok(event) => Some((Ok(event), Some(socket))),
301	                    Err(error) => Some((Err(error), None)),
302	                },
303	                Some(Ok(Message::Close(frame))) => match frame {
304	                    // A normal closure ends the stream; anything else is a
305	                    // transient drop the resume loop recovers from.
306	                    Some(frame) if frame.code == CloseCode::Normal => None,
307	                    Some(frame) => Some((
308	                        Err(ClientError::unavailable(format!(
309	                            "websocket closed abnormally ({} {})",
310	                            frame.code, frame.reason
311	                        ))),
312	                        None,
313	                    )),
314	                    None => Some((
315	                        Err(ClientError::unavailable(
316	                            "websocket closed without a close frame",
317	                        )),
318	                        None,
319	                    )),
320	                },
321	                Some(Ok(Message::Ping(_) | Message::Pong(_) | Message::Frame(_))) => continue,
322	                Some(Err(source)) => Some((
323	                    Err(ClientError::unavailable(format!(
324	                        "websocket transport failed: {source}"
325	                    ))),
326	                    None,
327	                )),
328	            };
329	        }
330	    })
331	    .boxed()
332	}
