334	/// Decodes one server frame: a `StreamedEvent` yields its core event, a
335	/// `{"error": <WireError>}` frame yields the mapped taxonomy error.
336	fn decode_frame(bytes: &[u8]) -> Result<Event, ClientError> {
337	    #[derive(serde::Deserialize)]
338	    struct ErrorFrame {
339	        error: WireError,
340	    }
341	    if let Ok(frame) = serde_json::from_slice::<ErrorFrame>(bytes) {
342	        return Err(ClientError::from_wire_error(frame.error));
343	    }
344	    let streamed = serde_json::from_slice::<StreamedEvent>(bytes).map_err(|source| {
345	        ClientError::server(format!(
346	            "event stream frame is neither a StreamedEvent nor an error frame: {source}"
347	        ))
348	    })?;
349	    streamed
350	        .decode_event()
351	        .map_err(ClientError::from_wire_error)
352	}
