97	async fn fetch(
98	    router: &Router,
99	    fields: serde_json::Value,
100	) -> Result<TranscriptFetchResponse, Box<dyn std::error::Error>> {
101	    let request = transcript_request(fields)?;
102	    let response = router
103	        .clone()
104	        .oneshot(json_request("/workflows/transcript", &request)?)
105	        .await?;
106	    if response.status() != StatusCode::OK {
107	        return Err(format!("transcript request failed with {}", response.status()).into());
