112	fn transcript_request(
113	    fields: serde_json::Value,
114	) -> Result<serde_json::Map<String, serde_json::Value>, Box<dyn std::error::Error>> {
115	    let mut request = match fields {
116	        serde_json::Value::Object(request) => request,
117	        _other => return Err("transcript request fields must be an object".into()),
118	    };
119	    request.insert("namespace".to_owned(), json!(NAMESPACE));
120	    request.insert("workflow_id".to_owned(), json!(workflow_id()));
121	    // The run is a required axis of the stream identity, so every request built
122	    // here names the same run the seeded events were written under.
123	    request.insert("run_id".to_owned(), json!(run_id()));
124	    request.insert("activity_id".to_owned(), json!(3));
125	    request.insert("attempt".to_owned(), json!(1));
126	    Ok(request)
127	}
