137	async fn router_with_transcript(count: u64) -> Result<Router, Box<dyn std::error::Error>> {
138	    let (engine, _store, _visibility) = shared_engine().await?;
139	    let ownership = StaticWorkflowNamespaces::default();
140	    ownership.record(workflow_id(), NAMESPACE)?;
141	    let resolver = NamespaceResolver::from_parts(
142	        NamespaceMode::SharedEngine,
143	        Some(engine),
144	        Arc::new(ownership),
145	        Arc::new(StaticScheduleNamespaces::default()),
146	    );
147	    let state = server_state(resolver, runtime_config()).await?;
148	    for seq in 0..count {
149	        let assigned = state
150	            .transcript_publisher()
151	            .publish(&activity_event(seq))
152	            .await?;
153	        if assigned != Some(seq) {
154	            return Err(format!("expected transcript store_seq {seq}, got {assigned:?}").into());
155	        }
156	    }
157	    Ok(workflow_router(state))
158	}
