102	      ...(params.limit === undefined ? {} : { limit: params.limit }),
103	      ...(params.last === undefined ? {} : { last: params.last }),
104	    };
105	    const responseBody = await this.post(TRANSCRIPT_READ.fetch, body);
106	    const responseRecord = isRecord(responseBody) ? responseBody : null;
107	    const events = responseRecord?.events;
108	    if (responseRecord === null || !Array.isArray(events)) {
109	      throw new ApiError(200, 'workflows/transcript response missing an events array');
110	    }
111	    const nextFromSeq = responseRecord.next_from_seq;
112	    const headSeq = responseRecord.head_seq;
113	    if (nextFromSeq !== null && !isSequence(nextFromSeq)) {
114	      throw new ApiError(200, 'workflows/transcript response has an invalid next_from_seq');
115	    }
116	    if (!isSequence(headSeq)) {
117	      throw new ApiError(200, 'workflows/transcript response has an invalid head_seq');
118	    }
119	    return {
120	      events: events as ActivityEvent[],
121	      nextFromSeq,
122	      headSeq,
123	    };
124	  }
