137	    runId: RunId
138	  ): Promise<RetainedStreamHead[]> {
139	    const responseBody = await this.post(TRANSCRIPT_READ.streams, {
140	      namespace,
141	      workflow_id: workflowId,
142	      run_id: runId,
143	    });
