2	
3	import { Button } from '@/components/ui';
4	
5	import type { TranscriptEntry } from '../hooks/useTranscript';
6	import { TranscriptEntryRow } from './TranscriptEventRow';
7	
8	const FOLLOW_THRESHOLD_PX = 48;
9	export const TRANSCRIPT_DOM_WINDOW_SIZE = 200;
10	
11	export type TranscriptListProps = {
12	  entries: TranscriptEntry[];
13	  hasEarlier?: boolean;
14	  isLoadingEarlier?: boolean;
15	  onLoadEarlier?: () => Promise<void>;
16	};
17	
18	/** A fixed-size DOM page over the bounded transcript source window. */
19	export function TranscriptList({
20	  entries,
21	  hasEarlier = false,
22	  isLoadingEarlier = false,
23	  onLoadEarlier,
24	}: TranscriptListProps) {
25	  const listRef = useRef<HTMLOListElement | null>(null);
26	  const seenTailKeysRef = useRef<Set<string> | null>(null);
27	  const [following, setFollowing] = useState(true);
28	  const [pageOffset, setPageOffset] = useState(0);
29	  const maxOffset = Math.max(0, entries.length - TRANSCRIPT_DOM_WINDOW_SIZE);
30	  const boundedOffset = Math.min(pageOffset, maxOffset);
31	  const end = entries.length - boundedOffset;
32	  const start = Math.max(0, end - TRANSCRIPT_DOM_WINDOW_SIZE);
33	  const visibleEntries = useMemo(() => entries.slice(start, end), [end, entries, start]);
34	  const seenTailKeys = seenTailKeysRef.current;
35	
36	  const handleScroll = () => {
37	    const list = listRef.current;
38	    if (list === null || boundedOffset > 0) {
39	      return;
40	    }
41	    const distanceFromBottom = list.scrollHeight - list.scrollTop - list.clientHeight;
42	    setFollowing(distanceFromBottom <= FOLLOW_THRESHOLD_PX);
43	  };
44	
45	  const jumpToLatest = () => {
46	    setPageOffset(0);
47	    const list = listRef.current;
48	    if (list !== null) {
49	      list.scrollTop = list.scrollHeight;
50	    }
51	    setFollowing(true);
52	  };
53	
54	  const showEarlier = async () => {
55	    if (start > 0) {
56	      setPageOffset((current) => Math.min(maxOffset, current + TRANSCRIPT_DOM_WINDOW_SIZE));
57	      setFollowing(false);
58	      return;
59	    }
60	    if (hasEarlier && onLoadEarlier !== undefined) {
61	      await onLoadEarlier();
62	      // Pin to the oldest mounted page after the newly fetched prefix commits.
63	      setPageOffset(Number.MAX_SAFE_INTEGER);
64	      setFollowing(false);
65	    }
66	  };
67	
68	  useLayoutEffect(() => {
69	    const list = listRef.current;
70	    if (!following || boundedOffset > 0 || list === null || entries.length === 0) {
71	      return;
72	    }
73	    list.scrollTop = list.scrollHeight;
74	  }, [boundedOffset, entries, following]);
75	
76	  useLayoutEffect(() => {
77	    if (boundedOffset === 0) {
78	      seenTailKeysRef.current = new Set(visibleEntries.map((entry) => entry.key));
79	    }
80	  }, [boundedOffset, visibleEntries]);
81	
82	  const canShowEarlier = start > 0 || hasEarlier;
83	
84	  return (
85	    <div className="relative flex min-h-0 flex-1 flex-col">
86	      {canShowEarlier ? (
87	        <div className="flex justify-center pb-2">
88	          <Button
89	            className="h-7 px-3 text-xs"
90	            disabled={isLoadingEarlier}
91	            onClick={() => void showEarlier()}
92	            type="button"
93	            variant="ghost"
94	          >
95	            {isLoadingEarlier ? 'Loading earlier…' : 'Show earlier'}
96	          </Button>
97	        </div>
98	      ) : null}
99	      <ol
100	        className="max-h-[70vh] min-h-0 flex-1 overflow-y-auto"
101	        data-testid="transcript-scroll"
102	        onScroll={handleScroll}
103	        ref={listRef}
104	      >
105	        {visibleEntries.map((entry) => (
106	          <TranscriptEntryRow
107	            entry={entry}
108	            isNew={boundedOffset === 0 && seenTailKeys !== null && !seenTailKeys.has(entry.key)}
109	            key={entry.key}
110	          />
111	        ))}
112	      </ol>
113	      {!following || boundedOffset > 0 ? (
114	        <Button
115	          className="absolute right-3 bottom-3 h-7 px-3 text-xs shadow-md"
116	          onClick={jumpToLatest}
117	          type="button"
118	          variant="outline"
119	        >
120	          Jump to latest
121	        </Button>
122	      ) : null}
123	    </div>
124	  );
125	}

