1	import { useQueryClient } from '@tanstack/react-query';
2	import { useEffect, useMemo, useRef, useState } from 'react';
3	
4	import { type EventSubscriptionManager, useBatchedEventSubscription } from '@/features/live-feed';
5	import { isSelectedNamespace, useNamespace } from '@/features/namespace';
6	import type { ResyncHandler, WorkflowEventSubscriptionFilter } from '@/lib/api';
7	import type { Event, WorkflowId } from '@/types';
8	import { type TimelineProjection, updateTimelineProjection } from '../lib/incrementalTimeline';
9	import {
10	  eventSequence,
11	  isTerminalWorkflowEvent,
12	  mergeEventsBySequence,
13	  mergeEventWindowBySequence,
14	  terminalOutcomeForMergedEvents,
15	} from '../lib/timeline';
16	import type { LifecycleOutcome, TimelineEntry } from '../types';
17	import { HISTORY_WINDOW_SIZE, workflowHistoryQueryKey } from './useWorkflowHistory';
18	
19	export type LiveWorkflowEventsOptions = {
20	  enabled?: boolean;
21	  history: readonly Event[];
22	  manager?: EventSubscriptionManager;
23	  onResync?: ResyncHandler;
24	  workflowId: WorkflowId;
25	};
26	
27	export type LiveWorkflowEvents = {
28	  events: Event[];
29	  isTerminal: boolean;
30	  lastSeenSequence: number | undefined;
31	  terminalOutcome: LifecycleOutcome | null;
32	  timeline: TimelineEntry[];
33	};
34	
35	export function useLiveWorkflowEvents({
36	  enabled = true,
37	  history,
38	  manager,
39	  onResync,
40	  workflowId,
41	}: LiveWorkflowEventsOptions): LiveWorkflowEvents {
42	  const { selectedNamespace } = useNamespace();
43	  const queryClient = useQueryClient();
44	  const identityKey = `${selectedNamespace ?? ''}:${workflowId}`;
45	  const [liveState, setLiveState] = useState<{ identityKey: string; events: Event[] }>(() => ({
46	    identityKey,
47	    events: [],
48	  }));
49	  const liveEvents = liveState.identityKey === identityKey ? liveState.events : [];
50	  const currentIdentity = useRef(identityKey);
51	  const projectionRef = useRef<{ identityKey: string; value: TimelineProjection | null }>({
52	    identityKey,
53	    value: null,
54	  });
55	  currentIdentity.current = identityKey;
56	
57	  useEffect(() => {
58	    setLiveState((current) =>
59	      current.identityKey === identityKey ? current : { identityKey, events: [] }
60	    );
61	  }, [identityKey]);
62	
63	  const historyWindow = useMemo(() => mergeEventsBySequence(history, []), [history]);
64	  const mergedEvents = useMemo(
65	    () =>
66	      mergeEventWindowBySequence(
67	        historyWindow,
68	        liveEvents,
69	        historyWindow.length + HISTORY_WINDOW_SIZE
70	      ),
71	    [historyWindow, liveEvents]
72	  );
73	  const terminalOutcome = useMemo(
74	    () => terminalOutcomeForMergedEvents(mergedEvents),
75	    [mergedEvents]
76	  );
77	  const lastSeenSequence = useMemo(() => latestSequence(mergedEvents), [mergedEvents]);
78	  const timeline = useMemo(() => {
79	    const cached = projectionRef.current;
80	    const previous = cached.identityKey === identityKey ? cached.value : null;
81	    const value = updateTimelineProjection(previous, mergedEvents);
82	    projectionRef.current = { identityKey, value };
83	    return value.timeline;
84	  }, [identityKey, mergedEvents]);
85	  const subscriptionFilter = useMemo<WorkflowEventSubscriptionFilter | null>(() => {
86	    if (!enabled || !isSelectedNamespace(selectedNamespace) || terminalOutcome !== null) {
87	      return null;
88	    }
89	    return { kind: 'workflow', namespace: selectedNamespace, workflowId };
90	  }, [enabled, selectedNamespace, terminalOutcome, workflowId]);
91	
92	  useBatchedEventSubscription({
93	    enabled: subscriptionFilter !== null,
94	    filter: subscriptionFilter,
95	    lastSeenSequence,
96	    manager,
97	    flushAfter: isTerminalWorkflowEvent,
98	    onEvents: (events) => {
99	      if (currentIdentity.current !== identityKey) {
100	        return;
101	      }
102	      setLiveState((current) => ({
103	        identityKey,
104	        events: mergeEventWindowBySequence(
105	          current.identityKey === identityKey ? current.events : [],
106	          events,
107	          HISTORY_WINDOW_SIZE
108	        ),
109	      }));
110	    },
111	    onResync: async (context) => {
112	      if (isSelectedNamespace(selectedNamespace)) {
113	        const queryKey = workflowHistoryQueryKey(selectedNamespace, workflowId);
114	        const cancelStaleQuery = () => {
115	          void queryClient.cancelQueries({ queryKey });
116	        };
117	        context.signal.addEventListener('abort', cancelStaleQuery, { once: true });
118	        try {
119	          await queryClient.invalidateQueries({ queryKey }, { throwOnError: true });
120	        } finally {
121	          context.signal.removeEventListener('abort', cancelStaleQuery);
122	        }
123	      }
124	      if (!context.isCurrent()) {
125	        return;
126	      }
127	      await onResync?.(context);
128	    },
129	  });
130	
131	  return {
132	    events: mergedEvents,
133	    isTerminal: terminalOutcome !== null,
134	    lastSeenSequence,
135	    terminalOutcome,
136	    timeline,
137	  };
138	}
139	
140	function latestSequence(events: readonly Event[]): number | undefined {
141	  const latest = events.at(-1);
142	  return latest === undefined ? undefined : eventSequence(latest);
143	}

1	import type { Event, RunId } from '@/types';
2	
3	import type { ActivityTimelineEntry, TimelineEntry } from '../types';
4	
5	/**
6	 * The DURABLE attempt navigator (NOI post-mortem fix).
7	 *
8	 * The old attempts panel enumerated only the LIVE intervenable attempts
9	 * (`POST /workflows/attempts`), which returns empty for a terminal run — so a
10	 * failed/finished workflow's attempts went blank and their (durable) transcripts
11	 * were unreachable. This module instead derives the selectable attempt list from
12	 * the projected timeline (durable history + live), so every attempt a run ever ran
13	 * stays selectable after the run ends.
14	 *
15	 * Each row is one `(activityId, attempt)` — the STABLE identity across the whole
16	 * lifecycle (`ActivityStarted/Completed/Failed/Cancelled` all carry the same
17	 * one-based `attempt`). Rows and the current selection are keyed by that durable
18	 * identity, NEVER by array index (indexes shift as live events extend the
19	 * timeline; the durable key survives refresh and post-mortem). `attempt: 0` is the
20	 * legacy/unknown sentinel (never a real attempt) — it is labelled distinctly and
21	 * remains selectable.
22	 *
23	 * # The generation each row belongs to
24	 *
25	 * One workflow id spans a whole continue-as-new chain, and ordinals + attempts
26	 * restart in every generation — so `(activityId, attempt)` names a coordinate,
27	 * not an attempt, and a transcript cannot be addressed without the run. The run
28	 * is recovered from the history itself: a `WorkflowStarted` opens a generation
29	 * and every later event belongs to it until the next one. The loaded history is
30	 * a WINDOW (the tail), so a row can genuinely precede any loaded
31	 * `WorkflowStarted`; that row's `runId` is `null` — the honest "this window
32	 * cannot say which generation" — and the caller must not address a transcript
33	 * with it. `null` is never papered over with a nearby run.
34	 */
35	
36	/** Terminal state of one `(activityId, attempt)`, derived from its terminal event. */
37	export type AttemptStatus = 'started' | 'completed' | 'failed' | 'cancelled';
38	
39	export type AttemptNavigatorRow = {
40	  /**
41	   * Durable identity `${runId}:${activityId}:${attempt}` (the run is `-` when the
42	   * loaded window cannot name it). Survives refresh + post-mortem and is the sole
43	   * selection key (never an array index).
44	   */
45	  key: string;
46	  /**
47	   * The generation this attempt ran in, or `null` when no `WorkflowStarted` for
48	   * it is inside the loaded history window. A `null` row is NOT addressable as a
49	   * transcript stream.
50	   */
51	  runId: RunId | null;
52	  activityId: string;
53	  /** Human activity type when the schedule is known; otherwise `null`. */
54	  activityType: string | null;
55	  /** One-based attempt number; `0` is the legacy/unknown sentinel. */
56	  attempt: number;
57	  /** True for the `attempt: 0` legacy sentinel (still selectable, labelled apart). */
58	  isLegacy: boolean;
59	  status: AttemptStatus;
60	};
61	
62	/**
63	 * The one true selection key for one attempt. The run leads the key because it
64	 * leads the identity: two generations of a chain otherwise produce the same
65	 * string for two different attempts. An unresolvable run is written `-`, which
66	 * cannot collide with a UUID.
67	 */
68	export function attemptRowKey(
69	  runId: RunId | null,
70	  activityId: string | number,
71	  attempt: number
72	): string {
73	  return `${runId ?? '-'}:${activityId}:${attempt}`;
74	}
75	
76	/** The attempt-bearing terminal/start events for one activity (all carry `attempt`). */
77	type AttemptEventType =
78	  | 'ActivityStarted'
79	  | 'ActivityCompleted'
80	  | 'ActivityFailed'
81	  | 'ActivityCancelled';
82	
83	const ATTEMPT_EVENT_TYPES = new Set<Event['type']>([
84	  'ActivityStarted',
85	  'ActivityCompleted',
86	  'ActivityFailed',
87	  'ActivityCancelled',
88	]);
89	
90	function isAttemptEvent(event: Event): event is Extract<Event, { type: AttemptEventType }> {
91	  return ATTEMPT_EVENT_TYPES.has(event.type);
92	}
93	
94	/** Accumulated presence of each terminal for one attempt (order-independent). */
95	type AttemptSlot = {
96	  started: boolean;
97	  completed: boolean;
98	  failed: boolean;
99	  cancelled: boolean;
100	  /** The generation this attempt ran in; `null` when the window cannot name it. */
101	  runId: RunId | null;
102	  /** The one-based attempt number (`0` is the legacy sentinel). */
103	  attempt: number;
104	};
105	
106	function emptySlot(runId: RunId | null, attempt: number): AttemptSlot {
107	  return {
108	    started: false,
109	    completed: false,
110	    failed: false,
111	    cancelled: false,
112	    runId,
113	    attempt,
114	  };
115	}
116	
117	/**
118	 * A completed/cancelled attempt takes precedence over a failure, which takes
119	 * precedence over a bare start. (An attempt has exactly one real terminal, but we
120	 * resolve defensively so a malformed group never yields an ambiguous status.)
121	 */
122	function slotStatus(slot: AttemptSlot): AttemptStatus {
123	  if (slot.completed) {
124	    return 'completed';
125	  }
126	  if (slot.cancelled) {
127	    return 'cancelled';
128	  }
129	  if (slot.failed) {
130	    return 'failed';
131	  }
132	  return 'started';
133	}
134	
135	/**
136	 * Group every activity's attempt-bearing events by their one-based `attempt` and
137	 * emit one navigator row per `(activityId, attempt)`, ordered by activity then
138	 * attempt. Scheduled-only activities (no attempt has run yet) yield no rows —
139	 * there is no transcript to observe until an attempt starts.
140	 */
141	export function deriveAttemptNavigator(timeline: readonly TimelineEntry[]): AttemptNavigatorRow[] {
142	  const generations = deriveGenerations(timeline);
143	  const rows: AttemptNavigatorRow[] = [];
144	
145	  for (const entry of timeline) {
146	    if (entry.kind === 'activity') {
147	      rows.push(...activityRows(entry, generations));
148	    }
149	  }
150	
151	  // Generation order, not lexicographic run order: rows of one coordinate from
152	  // two generations must list oldest-first, the order they ran in.
153	  const runOrder = new Map(generations.map((generation, index) => [generation.runId, index]));
154	  return rows.sort((left, right) => compareRows(left, right, runOrder));
155	}
156	
157	/**
158	 * One generation boundary: the sequence at which a `WorkflowStarted` opened
159	 * `runId`. Ascending by `seq`.
160	 */
161	type Generation = { seq: number; runId: RunId };
162	
163	/**
164	 * Collect the generation boundaries present in the loaded window, ascending.
165	 *
166	 * ONLY `WorkflowStarted` opens a generation. `WorkflowReopened` also carries a
167	 * `run_id`, but it names the run it REOPENS — it does not begin a new one — so
168	 * treating it as a boundary would be a second, redundant statement of the same
169	 * fact and would misread a reopen that arrives out of order. The one authority
170	 * is the start event.
171	 */
172	export function deriveGenerations(timeline: readonly TimelineEntry[]): Generation[] {
173	  const generations: Generation[] = [];
174	  for (const entry of timeline) {
175	    for (const event of entry.events) {
176	      if (event.type === 'WorkflowStarted') {
177	        generations.push({ seq: event.data.envelope.seq, runId: event.data.run_id });
178	      }
179	    }
180	  }
181	  return generations.sort((left, right) => left.seq - right.seq);
182	}
183	
184	/**
185	 * The generation an event at `seq` belongs to: the LAST `WorkflowStarted` at or
186	 * before it. `null` when the window holds no start at or before `seq` — the
187	 * honest answer for a tail window that begins mid-generation.
188	 */
189	function generationAt(generations: readonly Generation[], seq: number): RunId | null {
190	  let resolved: RunId | null = null;
