29	
30	/**
31	 * Agent-transcript live-stream client (NOI-7).
32	 *
33	 * The server keeps `/events/stream` strictly one-subscription-per-socket, so the
34	 * transcript channel is a NEW ARM of the single subscription frame, NOT a second
35	 * subscription multiplexed over the workflow socket. The honest client is a
36	 * DEDICATED socket bound to ONE `(namespace, workflow, activity, attempt)` target:
37	 * it opens `/events/stream`, sends exactly one `{ subscription: { transcript: … } }`
38	 * frame, then receives the durable `activity_event` tail followed by live
39	 * `activity_event` deltas (and, on overflow, a terminal `transcript_lagged` error).
40	 *
41	 * REAL DATA ONLY, socket-first, NO polling: there is no `setInterval` anywhere.
42	 * Resume is by `store_seq` (the server-stamped commit sequence): the manager
43	 * tracks the highest applied `store_seq` and re-requests `after_seq` on reconnect,
44	 * so the server suppresses records `store_seq <= after_seq` and splices the live
45	 * tail with no gap and no duplicate. Ephemeral token deltas carry `store_seq: null`
46	 * and are forwarded live but never advance the resume cursor (they are never
47	 * replayed). A `transcript_lagged` terminal keeps the cursor: the durable `O` tail
48	 * is authoritative, so the next connect re-reads strictly after the last applied
49	 * `store_seq`.
50	 */
51	
52	/** Server-frame discriminator pinned by `aion-proto` (`StreamedActivityEvent`). */
53	const TRANSCRIPT_FRAME = {
54	  event: 'activity_event',
55	} as const;
56	
57	/** Wire keys on the client subscribe frame (mirrors `ws_subscription.rs`). */
58	const TRANSCRIPT_REQUEST = {
59	  type: 'type',
60	  subscribe: 'subscribe',
61	  subscription: 'subscription',
62	  transcript: 'transcript',
63	  namespace: 'namespace',
64	  workflowId: 'workflow_id',
65	  runId: 'run_id',
66	  activityId: 'activity_id',
67	  attempt: 'attempt',
68	  afterSeq: 'after_seq',
69	} as const;
70	
71	/**
72	 * The `(namespace, workflow, run, activity, attempt)` target of one transcript
73	 * socket.
74	 *
75	 * `runId` is REQUIRED — the server answers a run-less transcript subscription
76	 * with `invalid_input`. Activity ordinals and attempt numbers restart in every
77	 * generation of a continue-as-new chain, so the remaining axes do not name a
78	 * stream: a run-less subscribe would tail whichever generation happened to own
79	 * the coordinate.
80	 */
81	export type TranscriptTarget = {
82	  namespace: Namespace;
83	  workflowId: WorkflowId;
84	  runId: RunId;
85	  activityId: ActivityId;
86	  attempt: number;
87	};
88	
89	export type TranscriptStreamListener = {
90	  /** A single transcript event — durable replay OR live delta. */
91	  onEvent: (event: ActivityEvent) => void;
92	};
93	
94	export type TranscriptStreamManagerOptions = {
95	  target: TranscriptTarget;
96	  baseUrl?: string;
97	  credentials?: SocketCredentials;
98	  webSocketImpl?: WebSocketConstructor;
99	  scheduler?: Scheduler;
100	  reconnect?: Partial<ReconnectOptions>;
101	  warn?: WarningLogger;
102	  /**
103	   * Resume cursor seeded from a REST backfill: the subscribe frame carries
104	   * `after_seq` immediately (on the FIRST connect), so the WS serves only the
105	   * live tail past the fetched history.
106	   */
107	  initialAfterSeq?: number;
108	};
109	
110	export type Unsubscribe = () => void;
111	
112	/**
113	 * Manages one dedicated transcript socket for a single attempt target. A single
114	 * subscriber drives the socket's lifetime: the first `subscribe()` opens it, the
115	 * last `unsubscribe()` closes it (the Set keeps StrictMode's double-mount safe).
116	 */
117	export class AionTranscriptStreamManager {
118	  private readonly target: TranscriptTarget;
119	  private readonly baseUrl: string;
120	  private readonly credentials: SocketCredentials | undefined;
121	  private readonly webSocketImpl: WebSocketConstructor;
122	  private readonly scheduler: Scheduler;
123	  private readonly reconnect: ReconnectOptions;
124	  private readonly warn: WarningLogger;
125	  private readonly listeners = new Set<TranscriptStreamListener>();
126	  private readonly statusListeners = new Set<StatusListener>();
