299	    // client lost live deltas. Surface it typed but KEEP the resume cursor — the
300	    // durable O tail is authoritative, so the next connect re-reads strictly
301	    // after the last applied store_seq (no gap, no duplicate).
302	    const lagged = readTranscriptLagged(frame);
