850	/// never touch the caller SDK.
851	async fn run(cli: &Cli, command: &ClientCommand) -> Result<Value> {
852	    match command {
853	        ClientCommand::New(args) => new::run(args),
854	        ClientCommand::Generate { path, check } => generate::run(path, *check),
855	        ClientCommand::Check {
856	            path,
857	            deterministic,
858	        } => check_deterministic::run(path, *deterministic),
859	        ClientCommand::Input {
860	            workflow_type,
861	            path,
862	        } => input::run(path, workflow_type),
863	        ClientCommand::Package { path, out, build } => package::run(path, out.as_deref(), *build),
864	        ClientCommand::Deploy { archive } => {
865	            if one_motion::is_awl(archive) {
866	                let (_, _, bytes) = one_motion::package_file(archive)?;
867	                deploy::deploy_bytes(&deploy_target(cli), bytes).await
868	            } else {
869	                deploy::deploy(&deploy_target(cli), archive).await
870	            }
871	        }
