873	            file,
874	            input,
875	            timeout,
876	        } => {
877	            let prepared = one_motion::prepare_run(file, input)?;
878	            deploy::deploy_bytes(&deploy_target(cli), prepared.archive).await?;
879	            let client = build_client(cli).await?;
880	            let handle =
881	                start_workflow_handle(&client, &prepared.workflow_name, prepared.input).await?;
882	            one_motion::await_result(handle, &prepared.workflow_name, *timeout).await
883	        }
884	        ClientCommand::Versions { workflow_type } => {
885	            deploy::versions(&deploy_target(cli), workflow_type.as_deref()).await
886	        }
887	        ClientCommand::Route {
888	            workflow_type,
889	            content_hash,
