701	#[tokio::main]
702	async fn main() -> ExitCode {
703	    let cli = match parse_or_refuse() {
704	        Ok(cli) => cli,
705	        Err(code) => return code,
706	    };
707	    if let Some(refusal) = launcher_flag_refusal(&cli) {
708	        eprintln!("{refusal}");
709	        return ExitCode::from(2);
710	    }
711	    match cli.command {
712	        // Bare `aion`: the launcher. Start the server in the background (or
713	        // this terminal with `--foreground`), wait until it answers its own
714	        // liveness probe, report in plain language, open the ops console.
715	        None => {
716	            // The launcher starts a server, so the same refusal applies: a
717	            // dial address is not a bind address (see the Server arm below).
718	            if let Some(refusal) = server_endpoint_refusal(cli.endpoint.as_deref()) {
719	                eprintln!("{refusal}");
720	                return ExitCode::from(2);
721	            }
722	            launch::run(cli.foreground, cli.no_open).await
723	        }
724	        // The server owns its own reporting contract: tracing-logged errors
725	        // and the operations exit codes (2 = config, 130 = forced).
726	        Some(Command::Server(ref args)) => {
727	            // `--endpoint` is a client dial address. It was accepted here and
728	            // silently dropped, so an operator who passed it to move the bind
729	            // got a server on the default port instead — which, on a box
730	            // already running one, means a collision or a second process
731	            // reaching for state the operator thought they had moved away
732	            // from. Refuse: a bind address the operator named and did not get
733	            // is not a thing to start up and hope about.
734	            if let Some(refusal) = server_endpoint_refusal(cli.endpoint.as_deref()) {
735	                eprintln!("{refusal}");
736	                return ExitCode::from(2);
737	            }
738	            // Report the agent harness composed into this binary at the root
739	            // (§3A.3): the default build ships Norn out-of-box; a
740	            // `--no-default-features` build reports none. The worker drives
741	            // whichever harness is compiled in through the neutral trait.
742	            harness::announce_composed_harness();
743	            // `--open` is a CLI-only nicety: resolve the served URL from the
744	            // effective config and, once the listener is reachable, open it in
745	            // the browser. Best-effort — a failure to open never blocks the run.
746	            if args.open() {
747	                server::spawn_browser_open(&args.clone().into());
748	            }
749	            aion_server::run(args.clone().into()).await
750	        }
751	        Some(Command::Dev(ref args)) => {
752	            // The dev loop runs locally and drives the running server over the
753	            // same operator deploy RPC `aion deploy` uses; it reports through
754	            // the one client rendering contract.
755	            let result = dev::run(args, deploy_target(&cli))
756	                .await
757	                .and_then(|value| print_json(&value, cli.pretty));
758	            match result {
759	                Ok(()) => ExitCode::SUCCESS,
760	                Err(error) => {
761	                    eprintln!("{}", render::render_error(&error));
762	                    ExitCode::FAILURE
763	                }
764	            }
765	        }
766	        // The AWL authoring commands own their own compiler-style reporting
767	        // contract: diagnostics to stderr, a one-line summary to stdout.
768	        Some(Command::Awl { ref command }) => awl::run(command),
769	        Some(Command::Worker { ref command }) => {
770	            let result = match command {
771	                WorkerCommand::Shell(args) => worker_shell::run(args, &cli.endpoint()).await,
772	                // The AWL worker dials the global gRPC endpoint, exactly as
773	                // the shell worker does, and normalizes a scheme-less one.
774	                WorkerCommand::Awl(args) => worker_awl::run(args, &cli.endpoint()).await,
775	                // The agent worker registers into the namespace the global flag
776	                // names, and dials liminal candidates rather than `--endpoint`.
777	                WorkerCommand::Agent(args) => worker_agent::run(args, &cli.namespace).await,
778	                // The managed-fleet verbs are operator commands against a
779	                // RUNNING server, not worker processes this invocation hosts.
780	                // They print the server's own report as JSON, through the same
781	                // printer every other read uses.
782	                WorkerCommand::Status => worker_managed::status(&deploy_target(&cli))
783	                    .await
784	                    .and_then(|value| print_json(&value, cli.pretty)),
785	                WorkerCommand::Start { name } => worker_managed::start(&deploy_target(&cli), name)
786	                    .await
787	                    .and_then(|value| print_json(&value, cli.pretty)),
788	                WorkerCommand::Stop { name } => worker_managed::stop(&deploy_target(&cli), name)
789	                    .await
790	                    .and_then(|value| print_json(&value, cli.pretty)),
791	                WorkerCommand::Restart { name } => {
792	                    worker_managed::restart(&deploy_target(&cli), name)
793	                        .await
794	                        .and_then(|value| print_json(&value, cli.pretty))
795	                }
796	            };
797	            match result {
798	                Ok(()) => ExitCode::SUCCESS,
799	                Err(error) => {
800	                    eprintln!("{}", render::render_error(&error));
801	                    ExitCode::FAILURE
802	                }
803	            }
804	        }
805	        Some(Command::Assistant { ref command }) => {
806	            // The connection is a FACTORY, not a built client: the verb dials
807	            // only for the subcommands that need a server, and only after it has
808	            // validated what the operator typed. `document` and `describe` never
809	            // dial, so they answer on a machine with no server running.
810	            let result = assistant::run(command, || build_client(&cli))
811	                .await
812	                .and_then(|value| {
813	                    // `document` prints the document itself and has no JSON
814	                    // report; anything else prints its report.
815	                    if value.is_null() {
816	                        Ok(())
817	                    } else {
818	                        print_json(&value, cli.pretty)
819	                    }
820	                });
821	            match result {
822	                Ok(()) => ExitCode::SUCCESS,
823	                Err(error) => {
824	                    report_client_error(&error);
825	                    ExitCode::FAILURE
826	                }
827	            }
828	        }
829	        Some(Command::Client(ref command)) => {
830	            let result = run(&cli, command)
831	                .await
832	                .and_then(|value| print_json(&value, cli.pretty));
833	            match result {
834	                Ok(()) => ExitCode::SUCCESS,
835	                // The single rendering contract for every client subcommand:
836	                // the taxonomy class, server detail, error type, and hint go
837	                // to stderr; the process exits 1.
838	                Err(error) => {
839	                    report_client_error(&error);
840	                    ExitCode::FAILURE
841	                }
842	            }
843	        }
844	    }

