171	                .events
172	                .into_iter()
173	                .map(|event| (event.emitted_at, prefix(target), event)),
174	        );
175	        heads.push(transcript.head_seq.checked_sub(1));
176	    }
177	    backfill.sort_by_key(|(emitted_at, _, _)| *emitted_at);
178	    for (_, prefix, event) in backfill {
179	        println!("{prefix} {}", render_event(&event));
180	    }
181	    for target in targets
